Question: Write a function void sortData(int arr[], int size, char choice) that sorts the array in ascending ('a') or descending ('d') order.

Code:
#include <iostream>
#include <algorithm>
#include <functional>
using namespace std;

void sortData(int arr[], int size, char choice) {
    if (arr == nullptr || size <= 0) {
        return;
    }

    if (choice == 'a') {
        std::sort(arr, arr + size);
    } else if (choice == 'd') {
        std::sort(arr, arr + size, std::greater<int>());
    } else {
        // Handle invalid choice? For now, do nothing or default to ascending
        // Let's assume strict requirement: do nothing if invalid
    }
}

int main() {
    int arr[] = {64, 34, 25, 12, 22, 11, 90};
    int size = sizeof(arr) / sizeof(arr[0]);

    sortData(arr, size, 'a');

    for (int i = 0; i < size; i++)
        cout << arr[i] << " ";
    cout << endl;

    sortData(arr, size, 'd');
     for (int i = 0; i < size; i++)
        cout << arr[i] << " ";
    cout << endl;

    return 0;
}

Question: Write a function void findMissingElements(const int arr1[], int size1, const int arr2[], int size2, int result[], int& resultSize) that finds elements in arr1 but not in arr2 (both sorted).

Code:
#include <iostream>
using namespace std;

void findMissingElements(const int arr1[], int size1, const int arr2[], int size2, int result[], int& resultSize) {
    if (arr1 == nullptr && size1 > 0) return; // Error or assume empty?
    // If result is null, we can't write. 
    if (result == nullptr) {
        resultSize = 0;
        return;
    }

    // Two pointer approach O(N + M)
    int i = 0, j = 0, k = 0;

    // Handle potential nullptrs for inputs if sizes are 0
    // If arr2 is null/empty, all arr1 goes to result
    if (arr2 == nullptr || size2 <= 0) {
        if (arr1 != nullptr) {
            for (int x = 0; x < size1; x++) result[k++] = arr1[x];
        }
        resultSize = k;
        return;
    }
    if (arr1 == nullptr || size1 <= 0) {
        resultSize = 0;
        return;
    }

    while (i < size1 && j < size2) {
        if (arr1[i] < arr2[j]) {
            result[k++] = arr1[i];
            i++;
        } else if (arr1[i] > arr2[j]) {
            j++;
        } else {
            // Equal: skip both
            i++;
            j++;
        }
    }

    // Add remaining elements from arr1
    while (i < size1) {
        result[k++] = arr1[i];
        i++;
    }

    resultSize = k;
}

int main() {
    int arr1[] = {1, 2, 3, 4, 5, 10, 12};
    int arr2[] = {2, 4, 10};
    int result[20];
    int resultSize = 0;

    findMissingElements(arr1, 7, arr2, 3, result, resultSize);

    cout << "Missing Elements: ";
    for (int i = 0; i < resultSize; i++) {
        cout << result[i] << " ";
    }
    cout << endl;

    return 0;
}

Question: Write a function int findConsecutiveZeros(const char arr[]) that returns the maximum number of consecutive '0' characters.

Code:
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

int findConsecutiveZeros(const char arr[]) {
    if (arr == nullptr) {
        return 0;
    }

    int maxZeros = 0;
    int currentZeros = 0;

    for (int i = 0; arr[i] != '\0'; i++) {
        if (arr[i] == '0') {
            currentZeros++;
        } else {
            if (currentZeros > maxZeros) {
                maxZeros = currentZeros;
            }
            currentZeros = 0;
        }
    }
    // Check after loop finishes in case array ends with zeros
    if (currentZeros > maxZeros) {
        maxZeros = currentZeros;
    }

    return maxZeros;
}

int main() {
    const char arr1[] = "10010001";
    cout << "Max Consecutive Zeros: " << findConsecutiveZeros(arr1) << endl;

    const char arr2[] = "0000";
    cout << "Max Consecutive Zeros: " << findConsecutiveZeros(arr2) << endl;

    const char* arr3 = NULL;
    cout << "Max Consecutive Zeros: " << findConsecutiveZeros(arr3) << endl;

    return 0;
}

Question: Write a function void removeDuplicates(char arr[]) that removes duplicate characters from the string in-place.

Code:
#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

void removeDuplicates(char arr[]) {
    if (arr == nullptr) return;

    // Use a boolean map for O(1) space (256 constant) and O(N) time
    bool seen[256] = {false}; 
    int index = 0;

    for (int i = 0; arr[i] != '\0'; i++) {
        unsigned char c = (unsigned char)arr[i];
        if (!seen[c]) {
            seen[c] = true;
            arr[index++] = arr[i];
        }
    }
    arr[index] = '\0';
}

int main() {
    char arr1[] = "programming";
    removeDuplicates(arr1);
    cout << "Unique: " << arr1 << endl;

    char arr2[] = "aaaa";
    removeDuplicates(arr2);
    cout << "Unique: " << arr2 << endl;

    removeDuplicates(NULL); // Should not crash

    return 0;
}

