Question: Write a function void multiplyMatrices(int A[][MAX], int B[][MAX], int C[][MAX], int m, int n, int p) that multiplies two matrices.

Code:
#include <iostream>
#include <iomanip>
using namespace std;

const int MAX = 10;

void multiplyMatrices(int A[][MAX], int B[][MAX], int C[][MAX], int m, int n, int p) {
    if (m <= 0 || n <= 0 || p <= 0 || m > MAX || n > MAX || p > MAX) {
        return; // Or handle error
    }

    // Initialize result matrix C to 0
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            C[i][j] = 0;
        }
    }

    // Matrix multiplication O(m*n*p)
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            for (int k = 0; k < n; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

int main() {
    int A[MAX][MAX] = {
        {1, 2, 3},
        {4, 5, 6}
    }; // 2x3

    int B[MAX][MAX] = {
        {7, 8},
        {9, 1},
        {2, 3}
    }; // 3x2

    int C[MAX][MAX];

    multiplyMatrices(A, B, C, 2, 3, 2);

    cout << "Result matrix:" << endl;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            cout << C[i][j] << " ";
        }
        cout << endl;
    }

    // Robustness check
    multiplyMatrices(A, B, C, 20, 20, 20); // Should safely return

    return 0;
}

Question: Write a function void printPascalsTriangle(int n) that prints the first n rows of Pascal's Triangle.

Code:
#include <iostream>
using namespace std;

void printPascalsTriangle(int n) {
    if (n <= 0) return;

    for (int line = 1; line <= n; line++) {
        // Use long long to prevent overflow for larger n
        long long C = 1;
        for (int i = 1; i <= line; i++) {
            cout << C << " ";
            // Update C to the next coefficient
            // C(line, i) = C(line, i-1) * (line - i + 1) / i
            // Wait, my loop i is 1-based, matching term index.
            // Current C is C(line-1, i-1).
            // Next should be C(line-1, i).
            // Formula: C_next = C_curr * (N - K) / (K + 1) where N is row index (0-based) and K is term index.
            // Here 'line' is 1-based. So row index is line-1.
            // Term index is i-1.
            // C_next = C * ((line-1) - (i-1)) / ((i-1) + 1)
            // C_next = C * (line - i) / i.
            // This assumes we print C BEFORE update. Yes.
            // And use long long arithmetic.

            C = C * (line - i) / i;
        }
        cout << endl;
    }
}

int main() {
    printPascalsTriangle(5);
    // Robustness test for overflow range (still might overflow valid long long eventually but much better than int)
    printPascalsTriangle(10); 
    printPascalsTriangle(0);
    return 0;
}

Question: Write a function void reverseList(Node*& head) that reverses a singly linked list.

Code:
#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

void reverseList(Node*& head) {
    Node* prev = nullptr;
    Node* current = head;
    Node* next = nullptr;

    while (current != nullptr) {
        next = current->next;  // Store next node
        current->next = prev;  // Reverse current node's pointer
        prev = current;        // Move pointers one position ahead
        current = next;
    }
    head = prev;
}

void printList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " -> ";
        head = head->next;
    }
    cout << "NULL" << endl;
}

int main() {
    Node* head = new Node{1, new Node{2, new Node{3, nullptr}}};
    printList(head);

    reverseList(head);
    printList(head); // 3 -> 2 -> 1 -> NULL

    // Cleanup (simplified)
    while(head) {
        Node* t = head;
        head = head->next;
        delete t;
    }

    return 0;
}

Question: Design a base class `Vehicle` with `make` (string) and `year` (int). Derive two classes: `Car` (adding `numDoors` as int) and `Motorcycle` (adding `hasSidecar` as bool). Implement constructors for all classes.

