Question: Design a C++ class named `Book` with private attributes for `title` (string), `author` (string), and `isbn` (string). Include public methods `setTitle`, `setAuthor`, `setISBN` to set these values, and `displayBookInfo` to print all book details. Create an object of `Book` and demonstrate its usage.

Code:
#include <iostream>
#include <string>

class Book {
private:
    std::string title;
    std::string author;
    std::string isbn;

public:
    // Semantic Error: Setters declare local variables with the same name as the parameters,
    // shadowing the member variables. The member variables remain unassigned.
    void setTitle(std::string newTitle) {
        std::string title = newTitle; // This creates a local variable 'title', not assigning to 'this->title'
    }

    void setAuthor(std::string newAuthor) {
        std::string author = newAuthor; // This creates a local variable 'author'
    }

    void setISBN(std::string newISBN) {
        std::string isbn = newISBN; // This creates a local variable 'isbn'
    }

    void displayBookInfo() {
        std::cout << "Title: " << title << std::endl;
        std::cout << "Author: " << author << std::endl;
        std::cout << "ISBN: " << isbn << std::endl;
    }
};

int main() {
    Book myBook;
    myBook.setTitle("The Hobbit");
    myBook.setAuthor("J.R.R. Tolkien");
    myBook.setISBN("978-0345339683");

    // Due to the semantic error in setters, these will likely print empty strings
    // or default-constructed strings, not the values passed in setTitle/Author/ISBN.
    myBook.displayBookInfo();

    return 0;
}

Question: Define a class `Product` with private `name` (string), `price` (double), and a protected `discountRate` (double). Include public `getName()` and `getPrice()` methods. Create a derived class `SpecialProduct` that can access `discountRate` and apply it when calculating a final price using a public method.

Code:
#include <iostream>
#include <string>
#include <iomanip> // For std::fixed and std::setprecision

class Product {
private:
    std::string name;
    double price;
protected:
    double discountRate;

public:
    Product(std::string n, double p, double dr) : name(n), price(p), discountRate(dr) {}

    std::string getName() const {
        return name;
    }

    double getPrice() const {
        return price;
    }

    // This method is added to verify the base class's discount rate
    double getBaseDiscountRate() const {
        return discountRate;
    }

    void displayProduct() const {
        std::cout << "Product: " << name << ", Price: $" << std::fixed << std::setprecision(2) << price << ", Discount Rate: " << discountRate * 100 << "%" << std::endl;
    }
};

class SpecialProduct : public Product {
public:
    // Semantic Error: The constructor for SpecialProduct ignores its own 'dr' parameter
    // and always passes 0.0 as the discount rate to the base Product constructor.
    // This means the inherited 'discountRate' will always be 0.0, regardless of the intended discount.
    SpecialProduct(std::string n, double p, double dr) : Product(n, p, 0.0) {
        // The 'dr' passed to SpecialProduct constructor is effectively ignored for the base class's discountRate.
        // If we wanted to use 'dr' for SpecialProduct, we should have passed 'dr' to Product(n, p, dr).
    }

    double getFinalPrice() const {
        // This correctly accesses the protected discountRate from the base class,
        // but its value is always 0.0 due to the constructor's semantic error.
        return getPrice() * (1.0 - discountRate);
    }

    void displaySpecialProduct() const {
        std::cout << "Special Product: " << getName() << ", Original Price: $" << std::fixed << std::setprecision(2) << getPrice()
                  << ", Discount Rate (as seen by base): " << getBaseDiscountRate() * 100 << "%" // Verify base rate
                  << ", Intended Discount Rate (ignored by constructor): " << "N/A" // Cannot access original 'dr'
                  << ", Final Price: $" << getFinalPrice() << std::endl;
    }
};

int main() {
    Product p1("Book", 25.0, 0.0);
    p1.displayProduct();

    SpecialProduct sp1("Laptop", 1200.0, 0.10); // Intends 10% discount, but base gets 0%
    // Expected final price: $1080.00, but will output $1200.00 because base discountRate is 0.0
    sp1.displaySpecialProduct();

    SpecialProduct sp2("Mouse", 50.0, 0.05); // Intends 5% discount, but base gets 0%
    // Expected final price: $47.50, but will output $50.00 because base discountRate is 0.0
    sp2.displaySpecialProduct();

    return 0;
}

Question: Create a `StringWrapper` class that manages a C-style string (`char*`) allocated on the heap. Implement a constructor that takes a `const char*` and performs a deep copy, and a destructor that releases the dynamically allocated memory. Demonstrate memory leak prevention.

Code:
#include <iostream>
#include <cstring> // For strlen, strcpy

class StringWrapper {
public:
    char* data;

    // Constructor: Deep copy the C-style string
    StringWrapper(const char* s) {
        if (s == nullptr) {
            data = new char[1];
            data[0] = '\0';
        } else {
            size_t len = strlen(s);
            data = new char[len + 1]; // Allocate memory for string + null terminator
            strcpy(data, s);          // Deep copy
        }
    }

    // Destructor: Release dynamically allocated memory
    ~StringWrapper() {
        // SEMANTIC ERROR: Memory leak - 'data' is not deleted.
        // The dynamically allocated memory is never released.
    }

    // Getter for the string
    const char* getString() const {
        return data;
    }
};

int main() {
    std::cout << "--- Test Case 1 ---" << std::endl;
    StringWrapper s1("Hello World");
    std::cout << "Wrapped string: " << s1.getString() << std::endl;

    std::cout << "--- Test Case 2 ---" << std::endl;
    StringWrapper s2("C++ Programming");
    std::cout << "Wrapped string: " << s2.getString() << std::endl;

    std::cout << "--- Test Case 3 ---" << std::endl;
    StringWrapper s3(""); // Test empty string
    std::cout << "Wrapped string: " << s3.getString() << std::endl;

    std::cout << "--- Test Case 4 ---" << std::endl;
    StringWrapper s4("Short");
    std::cout << "Wrapped string: " << s4.getString() << std::endl;

    // Memory will be leaked here as s1, s2, s3, s4 go out of scope
    return 0;
}

